class Checkout:
    def __init__(self, gateway, tax_rate):
        self.gateway = gateway
        self.tax_rate = tax_rate

    def checkout(self, cart):
        subtotal = sum(item['price'] * item.get('quantity', 1) for item in cart)
        return self.gateway.charge(subtotal)

