import unittest
from decimal import Decimal
from solution import Checkout


class Gateway:
    def __init__(self): self.amounts = []
    def charge(self, amount): self.amounts.append(amount); return {'charged': amount}


class TestCheckout(unittest.TestCase):
    def test_taxed_total_charged_once(self):
        gateway = Gateway()
        result = Checkout(gateway, Decimal('0.20')).checkout([
            {'price': Decimal('10.00'), 'quantity': 2},
            {'price': Decimal('5.00')},
        ])
        self.assertEqual(result, {'charged': Decimal('30.0000')})
        self.assertEqual(gateway.amounts, [Decimal('30.0000')])


if __name__ == '__main__':
    unittest.main()
